{
  "eventSlug": "hackathon-2024",
  "eventTitle": "DevSoc Hackathon 2024",
  "formType": "payment",
  "isActive": true,
  "fields": [
    {
      "id": "name",
      "type": "text",
      "label": "Full Name",
      "placeholder": "Enter your full name",
      "required": true,
      "validation": {
        "minLength": 2,
        "maxLength": 100
      }
    },
    {
      "id": "email",
      "type": "email",
      "label": "Email Address",
      "placeholder": "your.email@example.com",
      "required": true
    },
    {
      "id": "phone",
      "type": "tel",
      "label": "Phone Number",
      "placeholder": "+91 9876543210",
      "required": true,
      "validation": {
        "pattern": "^[+]?[0-9\\s\\-\\(\\)]+$"
      }
    },
    {
      "id": "experience",
      "type": "radio",
      "label": "Programming Experience",
      "required": true,
      "options": ["Beginner", "Intermediate", "Advanced"]
    },
    {
      "id": "technologies",
      "type": "checkbox",
      "label": "Technologies You Know",
      "required": false,
      "options": ["JavaScript", "Python", "Java", "React", "Node.js"]
    },
    {
      "id": "resume",
      "type": "file",
      "label": "Upload Resume",
      "required": false,
      "validation": {
        "fileTypes": ["application/pdf", "application/msword"],
        "maxFileSize": 2097152
      }
    },
    {
      "id": "motivation",
      "type": "textarea",
      "label": "Why do you want to participate?",
      "placeholder": "Tell us about your motivation...",
      "required": true,
      "validation": {
        "minLength": 50,
        "maxLength": 500
      }
    }
  ],
  "paymentConfig": {
    "enabled": true,
    "amount": 500,
    "qrCodeUrl": "https://example.com/qr-code.png",
    "upiId": "devsoc@upi",
    "instructions": "Please pay the registration fee and upload the screenshot. Registration will be confirmed after payment verification."
  },
  "styling": {
    "theme": "dark",
    "primaryColor": "#3B82F6",
    "backgroundColor": "#1F2937"
  }
}

{
  "eventSlug": "workshop-react",
  "eventTitle": "React Workshop",
  "formType": "simple",
  "isActive": true,
  "fields": [
    {
      "id": "name",
      "type": "text",
      "label": "Full Name",
      "placeholder": "Enter your full name",
      "required": true
    },
    {
      "id": "email",
      "type": "email",
      "label": "Email Address",
      "placeholder": "your.email@example.com",
      "required": true
    },
    {
      "id": "experience_level",
      "type": "select",
      "label": "React Experience Level",
      "required": true,
      "options": ["Complete Beginner", "Some Experience", "Experienced"]
    }
  ],
  "paymentConfig": {
    "enabled": false,
    "amount": 0
  },
  "styling": {
    "theme": "light",
    "primaryColor": "#10B981",
    "backgroundColor": "#FFFFFF"
  }
}
